using System;using System.IO;using System.Linq;using System.Text;
namespace Dafeiyu.Tests {public static class ComposerDraftStoreTests {public static int Main(){try{int checks=0;Action<bool,string> check=(ok,m)=>{if(!ok)throw new Exception(m);checks++;};string root=Path.GetFullPath("work/draft-tests/"+Guid.NewGuid().ToString("N"));
string scope=ComposerDraftStore.Scope("official:e-bao","chat","unassigned","default");
using(var store=new ComposerDraftStore(root)){check(store.Get(scope)=="","new scope empty");store.Set(scope,"未发送的测试文字\n第二行");store.Flush();}
using(var store=new ComposerDraftStore(root)){check(store.Get(scope)=="未发送的测试文字\n第二行","new process owner restores text");check(store.Get(ComposerDraftStore.Scope("official:marfu","chat","unassigned","default"))=="","role isolation");check(store.Get(ComposerDraftStore.Scope("official:e-bao","work","unassigned","default"))=="","mode isolation");check(store.Get(ComposerDraftStore.Scope("official:e-bao","chat","other","default"))=="","project isolation");check(store.Get(ComposerDraftStore.Scope("official:e-bao","chat","unassigned","other"))=="","section isolation");check(Directory.GetFiles(Path.Combine(root,"composer-drafts")).All(f=>!Encoding.UTF8.GetString(File.ReadAllBytes(f)).Contains("未发送")),"no plain text on disk");store.Set(scope,"");}
using(var store=new ComposerDraftStore(root)){check(store.Get(scope)=="","accepted send clear persists");store.Set(scope,"recoverable");}
string file=Directory.GetFiles(Path.Combine(root,"composer-drafts"),"*.draft").Single();File.WriteAllBytes(file,new byte[]{1,2,3});using(var store=new ComposerDraftStore(root)){check(store.Get(scope)=="","bad encrypted record remains unavailable");store.Set(scope,"new text");store.Flush();check(!String.IsNullOrEmpty(store.Warning),"storage problem visible");}check(File.ReadAllBytes(file).SequenceEqual(new byte[]{1,2,3}),"corrupt record is never overwritten");
Console.WriteLine("PASS: "+checks+" encrypted composer draft checks");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}}}
